import { Component, OnInit } from '@angular/core';
import { jobSeeker } from 'src/app/auth/Models/jobSeeker';
import { JobseekerService } from 'src/app/service/jobseeker/jobseeker.service';

@Component({
  selector: 'app-my-profile',
  templateUrl: './my-profile.component.html',
  styleUrls: ['./my-profile.component.css']
})
export class MyProfileComponent implements OnInit {

  jobSeeker!: jobSeeker;

  constructor(private jobSeekerService: JobseekerService) {}

  ngOnInit(): void {
    this.getJobSeekerById();
  }

  get initials(): string {
    const name = `${this.jobSeeker?.firstName ?? ''} ${this.jobSeeker?.lastName ?? ''}`.trim();
    return name
      .split(' ')
      .filter(Boolean)
      .map(part => part.charAt(0))
      .join('')
      .substring(0, 2)
      .toUpperCase();
  }

  getJobSeekerById(): void {
    const id = Number(localStorage.getItem('id'));
    this.jobSeekerService.getJobSeekerById(id).subscribe({
      next: (result) => { this.jobSeeker = result; },
      error: (err) => { console.log(err); }
    });
  }
}
<div class="page">
<app-header variant="seeker"></app-header>
<div class="app-shell">
<app-sidebar variant="seeker"></app-sidebar>
<main class="main">

<div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:24px;">
  <div style="display:flex;gap:16px;align-items:center;">
    <div class="avatar" style="width:52px;height:52px;font-size:16px;">{{initials}}</div>
    <div><h2 style="font-size:20px;">{{jobSeeker?.firstName}} {{jobSeeker?.lastName}}</h2><p class="muted" style="font-size:13.5px;">{{jobSeeker?.location}}, IN</p></div>
  </div>
  <a routerLink="/seeker/profile-jobseeker/edit" class="btn btn-secondary btn-sm">Edit profile</a>
</div>
<div class="card-row">
  <div class="card">
    <h3 style="font-size:14px;margin-bottom:8px;">Contact</h3>
    <p style="font-size:13.5px;">{{jobSeeker?.email}}</p>
  </div>
  <div class="card">
    <h3 style="font-size:14px;margin-bottom:8px;">Skills</h3>
    <div class="skill-tags">
      <span *ngFor="let skill of jobSeeker?.skills" class="skill-tag">{{skill}}</span>
    </div>
  </div>
</div>
<div class="card" style="margin-top:20px;max-width:520px;">
  <h3 style="font-size:14px;margin-bottom:8px;">Resume</h3>
  <p style="font-size:13.5px;">{{jobSeeker?.resumeUrl || 'No resume uploaded yet'}}</p>
</div>

</main>
</div>
</div>
